-- THE HUMANITY & COOPERATION INITIATIVE (an ORIVANA initiative): schema.
-- Every table is prefixed hc_ so it can share a Supabase project with other apps. Safe to re-run.
create extension if not exists pgcrypto;
create extension if not exists pg_trgm;
create or replace function hc_touch() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;

-- Access control
create table if not exists hc_profiles (id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, phone text, organisation text, newsletter_pref boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists hc_roles (role text primary key, name text not null, description text, is_system boolean not null default false);
create table if not exists hc_role_permissions (role text not null references hc_roles(role) on delete cascade, permission text not null, primary key (role, permission));
create table if not exists hc_user_roles (user_id uuid not null references auth.users(id) on delete cascade, role text not null references hc_roles(role) on delete cascade, primary key (user_id, role));

-- Knowledge structure
create table if not exists hc_categories (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text, sort_order int not null default 0, is_active boolean not null default true, seo_title text, seo_description text, created_at timestamptz not null default now());
create table if not exists hc_topics (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, summary text, introduction text, why_it_matters text, objectives text, practical_tools text, exercises text, reflection_questions text, further_learning text, icon_image text, sort_order int not null default 0, is_published boolean not null default true, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists hc_tags (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null);
create table if not exists hc_authors (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, slug text not null unique, name text not null, photo_url text, bio text, designation text, organisation text, email text, show_email boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now());

create table if not exists hc_articles (
  id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, excerpt text, body text, status text not null default 'draft' check (status in ('draft','review','scheduled','published','archived')),
  category_id uuid references hc_categories(id) on delete set null, topic_id uuid references hc_topics(id) on delete set null, author_id uuid references hc_authors(id) on delete set null, writer_user_id uuid references auth.users(id) on delete set null,
  featured_image text, image_alt text, image_credit text, related_ids uuid[] not null default '{}', publish_at timestamptz, published_at timestamptz, is_featured boolean not null default false, is_visible boolean not null default true,
  reading_time int, seo_title text, seo_description text, is_sample boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists hc_articles_status_idx on hc_articles(status, published_at desc);
create index if not exists hc_articles_topic_idx on hc_articles(topic_id); create index if not exists hc_articles_cat_idx on hc_articles(category_id);
create index if not exists hc_articles_title_trgm on hc_articles using gin (title gin_trgm_ops);
create table if not exists hc_article_tag_relations (article_id uuid not null references hc_articles(id) on delete cascade, tag_id uuid not null references hc_tags(id) on delete cascade, primary key (article_id, tag_id));
create table if not exists hc_editorial_reviews (id uuid primary key default gen_random_uuid(), article_id uuid not null references hc_articles(id) on delete cascade, reviewer_id uuid, reviewer_email text, decision text not null check (decision in ('submitted','changes_requested','approved','published','returned')), comment text, created_at timestamptz not null default now());

-- Webinars
create table if not exists hc_speakers (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, photo_url text, bio text, designation text, organisation text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists hc_webinars (
  id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, summary text, description text, topic_id uuid references hc_topics(id) on delete set null, speaker_ids uuid[] not null default '{}',
  starts_at timestamptz, ends_at timestamptz, timezone text not null default 'Asia/Kolkata', registration_url text, registration_details text, on_site_registration boolean not null default false, capacity int, join_url text,
  video_url text, recording_url text, status text not null default 'draft' check (status in ('draft','scheduled','completed','cancelled','archived')), is_published boolean not null default false, is_featured boolean not null default false,
  related_article_ids uuid[] not null default '{}', related_resource_ids uuid[] not null default '{}', image_url text, is_sample boolean not null default false, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists hc_webinar_materials (id uuid primary key default gen_random_uuid(), webinar_id uuid not null references hc_webinars(id) on delete cascade, title text not null, file_url text not null, sort_order int not null default 0);
create table if not exists hc_webinar_registrations (id uuid primary key default gen_random_uuid(), webinar_id uuid not null references hc_webinars(id) on delete cascade, name text not null, email text not null, organisation text, country text, status text not null default 'registered' check (status in ('registered','cancelled','attended')), created_at timestamptz not null default now(), unique (webinar_id, email));

-- Toolkit
create table if not exists hc_resource_categories (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text, sort_order int not null default 0);
create table if not exists hc_resources (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, description text, body text, category_id uuid references hc_resource_categories(id) on delete set null, topic_id uuid references hc_topics(id) on delete set null, kind text not null default 'guide', file_url text, external_url text, tags text[] not null default '{}', audience text, downloads int not null default 0, is_published boolean not null default true, is_featured boolean not null default false, is_sample boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

-- Stories, research
create table if not exists hc_stories (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, excerpt text, body text, featured_image text, image_alt text, author_name text, location text, category text, tags text[] not null default '{}', status text not null default 'draft' check (status in ('draft','review','published','archived')), published_at timestamptz, is_featured boolean not null default false, is_sample boolean not null default false, seo_title text, seo_description text, submitted_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists hc_research_items (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, kind text not null default 'perspective' check (kind in ('interview','conversation','research','report','knowledge_paper','perspective','expert_contribution','university_collaboration')), summary text, body text, author_name text, organisation text, file_url text, external_url text, image_url text, published_at timestamptz, is_published boolean not null default false, is_featured boolean not null default false, is_sample boolean not null default false, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

-- Programmes (youth, leadership, facilitator) and circles
create table if not exists hc_programmes (id uuid primary key default gen_random_uuid(), slug text not null unique, kind text not null check (kind in ('youth','leadership','facilitator')), title text not null, summary text, body text, audience text, format text, duration text, image_url text, is_published boolean not null default true, is_featured boolean not null default false, sort_order int not null default 0, is_sample boolean not null default false, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists hc_programme_modules (id uuid primary key default gen_random_uuid(), programme_id uuid not null references hc_programmes(id) on delete cascade, title text not null, summary text, body text, sort_order int not null default 0, is_published boolean not null default true);
create table if not exists hc_circles (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, setting text, location text, description text, status text not null default 'pending' check (status in ('pending','approved','archived')), is_published boolean not null default false, contact_name text, contact_email text, created_at timestamptz not null default now());
create table if not exists hc_circle_content (id uuid primary key default gen_random_uuid(), kind text not null check (kind in ('how_it_works','guideline','toolkit_activity','discussion_theme','facilitation','exercise')), title text not null, body text, sort_order int not null default 0, is_published boolean not null default true);
create table if not exists hc_forms (key text primary key, title text not null, description text, fields jsonb not null default '[]'::jsonb, success_message text, notify_email text, is_active boolean not null default true, updated_at timestamptz not null default now());
create table if not exists hc_form_submissions (id uuid primary key default gen_random_uuid(), form_key text not null references hc_forms(key) on delete cascade, data jsonb not null default '{}'::jsonb, email text, name text, status text not null default 'new' check (status in ('new','in_review','approved','declined','closed')), admin_note text, user_id uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create index if not exists hc_form_sub_idx on hc_form_submissions(form_key, created_at desc);

-- Global Cooperation Challenge
create table if not exists hc_challenge_areas (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text, sort_order int not null default 0);
create table if not exists hc_challenge_submissions (id uuid primary key default gen_random_uuid(), slug text unique, title text not null, area_id uuid references hc_challenge_areas(id) on delete set null, group_name text not null, location text, contact_name text not null, contact_email text not null, summary text not null, challenge_identified text, solution text, impact text, image_url text, link_url text, status text not null default 'submitted' check (status in ('submitted','under_review','approved','rejected','published','removed')), is_featured boolean not null default false, recognition text, admin_note text, user_id uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

-- Facilitators (applications and participants)
create table if not exists hc_facilitators (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, name text not null, email text not null, phone text, organisation text, location text, experience text, motivation text, programme_id uuid references hc_programmes(id) on delete set null, status text not null default 'applied' check (status in ('applied','under_review','approved','in_training','completed','declined','withdrawn')), admin_note text, completion_date date, certificate_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

-- Newsletter, support, sponsors
create table if not exists hc_newsletter_subscribers (id uuid primary key default gen_random_uuid(), email text not null unique, name text, status text not null default 'pending' check (status in ('pending','active','unsubscribed')), consent boolean not null default false, consent_at timestamptz, token text not null default encode(gen_random_bytes(16),'hex'), verified_at timestamptz, unsubscribed_at timestamptz, source text, created_at timestamptz not null default now());
create table if not exists hc_newsletter_campaigns (id uuid primary key default gen_random_uuid(), subject text not null, preheader text, body_html text, status text not null default 'draft' check (status in ('draft','scheduled','sending','sent')), scheduled_at timestamptz, sent_at timestamptz, recipients_total int not null default 0, sent_count int not null default 0, failed_count int not null default 0, last_subscriber_created timestamptz, created_at timestamptz not null default now());
create table if not exists hc_sponsors (id uuid primary key default gen_random_uuid(), name text not null, slug text unique, tier text not null default 'supporter' check (tier in ('founding_partner','programme_partner','event_sponsor','supporter','in_kind')), logo_url text, website text, blurb text, show_publicly boolean not null default false, show_on_articles boolean not null default false, show_on_webinars boolean not null default false, sort_order int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists hc_support_options (id uuid primary key default gen_random_uuid(), title text not null, description text, kind text not null default 'sponsorship' check (kind in ('sponsorship','institutional','donation','partnership','volunteer')), amount_note text, cta_label text, cta_url text, sort_order int not null default 0, is_active boolean not null default true);

-- Site management
create table if not exists hc_site_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create table if not exists hc_navigation_items (id uuid primary key default gen_random_uuid(), location text not null default 'header' check (location in ('header','footer')), label text not null, href text not null, parent_label text, sort_order int not null default 0, is_visible boolean not null default true);
create table if not exists hc_pages (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, body text, is_published boolean not null default true, seo_title text, seo_description text, updated_at timestamptz not null default now());
create table if not exists hc_seo_entries (id uuid primary key default gen_random_uuid(), path text not null unique, title text, description text, og_image text, noindex boolean not null default false);
create table if not exists hc_media (id uuid primary key default gen_random_uuid(), title text, url text not null, kind text not null default 'image', alt text, size_bytes int, uploaded_by uuid, created_at timestamptz not null default now());
create table if not exists hc_notifications (id uuid primary key default gen_random_uuid(), kind text not null, title text not null, body text, link text, permission text, is_read boolean not null default false, created_at timestamptz not null default now());
create table if not exists hc_audit_logs (id bigserial primary key, user_id uuid, user_email text, action text not null, resource text, resource_id text, details jsonb, created_at timestamptz not null default now());
create table if not exists hc_rate_limits (key text primary key, window_start timestamptz not null default now(), hits int not null default 0);
create table if not exists hc_page_views (day date not null default current_date, path text not null, views int not null default 0, primary key (day, path));
create table if not exists hc_article_views (article_id uuid not null references hc_articles(id) on delete cascade, day date not null default current_date, views int not null default 0, primary key (article_id, day));

do $$ declare t text; begin
  foreach t in array array['articles','topics','webinars','resources','stories','research_items','programmes','challenge_submissions','facilitators'] loop
    execute format('drop trigger if exists hc_touch_%1$s on hc_%1$s', t); execute format('create trigger hc_touch_%1$s before update on hc_%1$s for each row execute function hc_touch()', t);
  end loop; end $$;
